// One shape for every Telegram update, message or button tap.
// Everything later reads these fields instead of digging into the raw update.
const u = $('Telegram Trigger').first().json;
const msg = u.message || {};
const cb = u.callback_query;
const text = String(msg.text || '').trim();
const chatId = cb ? cb.message.chat.id : (msg.chat ? msg.chat.id : '');

let command = '';
let arg = text;
if (text.startsWith('/')) {
  const sp = text.indexOf(' ');
  command = (sp < 0 ? text : text.slice(0, sp)).toLowerCase().split('@')[0]; // "/add@MyBot" -> "/add"
  arg = sp < 0 ? '' : text.slice(sp + 1).trim();
}

// route decides the Switch branch. Empty, too long or unknown -> usage message.
// /lang, /level, /time and /words all share the "settings" branch.
const SETTINGS = ['/lang', '/level', '/time', '/words'];
let route = 'help';
if (cb) route = 'button';
else if (!text || text.length > 200) route = 'help';
else if (SETTINGS.includes(command)) route = 'settings';
else if (command === '/review') route = 'review';
else if (command === '/add') route = arg ? 'add' : 'help';
else if (command === '' || command === '/article') route = arg ? 'article' : 'help';

return [{ json: {
  chat_id: String(chatId),
  text, command, arg, route,
  callback_id: cb ? cb.id : '',
  callback_data: cb ? String(cb.data || '') : '',
  message_id: cb ? cb.message.message_id : null,
  message_text: cb ? String(cb.message.text || '') : ''
} }];

// Notion is the bot's memory: one Settings row per chat. No row yet -> defaults.
const cfg = $('Config').first().json;
const upd = $('Normalize The Update').first().json;
const row = ($json.results || [])[0];
const plain = (p) => ((p && (p.rich_text || p.title)) || []).map(t => t.plain_text).join('').trim().toLowerCase();
const source = row ? plain(row.properties['Source Language']) : '';
const target = row ? plain(row.properties['Target Language']) : '';
const level = row ? plain(row.properties['Level']) : '';
// level -> range of words to pick (a b2 learner gets b2-c1 words, not c2)
const RANGE = { a1: 'A1-A2', a2: 'A2-B1', b1: 'B1-B2', b2: 'B2-C1', c1: 'C1-C2', c2: 'C2' };
const lvl = RANGE[level] ? level : cfg.default_level;
return [{ json: {
  ...upd,
  source: source || cfg.default_source,
  target: target || cfg.default_target,
  level: lvl.toUpperCase(),
  level_range: RANGE[lvl],
  settings_page_id: row ? row.id : ''
} }];

// GNews q syntax treats quotes, parentheses and operators specially: keep words only.
const s = $json;
const topic = s.arg.replace(/["()]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 190);
return [{ json: { ...s, topic } }];

// Keep up to 5 GNews results, one item per article: the next nodes try all of them,
// because many news pages are paywalled or block bots. GNews errors (bad key, quota) arrive as
// {errors: [...]} with neverError on, and are kept so the reply can say what happened.
const articles = (Array.isArray($json.articles) ? $json.articles : []).filter(a => a && a.url).slice(0, 5);
if (!articles.length) {
  // errors = the request failed; information = plan notices (12-hour delay, 30-day limit)
  const why = $json.errors ? 'gnews error: ' + JSON.stringify($json.errors).slice(0, 150)
            : $json.information ? 'gnews returned nothing usable: ' + JSON.stringify($json.information).slice(0, 150)
            : 'gnews found no article for this topic';
  return [{ json: { found: false, reason: why } }];
}
return articles.map(a => ({ json: {
  found: true,
  url: a.url,
  title: String(a.title || ''),
  outlet: a.source ? String(a.source.name || '') : '',
  description: String(a.description || '')
} }));

// One item per fetched page, in the same order as List Articles: clean each one and keep
// the longest. Paywalls, cookie walls and JavaScript-only sites leave little text, so a page
// needs at least 800 characters of real paragraphs to count.
const listed = $('List Articles').all();
const pages = $('Fetch Article Pages').all();
const clean = (p) => String(p || '').replace(/\s+/g, ' ').trim();
const junk = /cookie|abonnez|subscribe|newsletter|javascript|publicité|consentement/i;
let best = null;
$input.all().forEach((item, i) => {
  let paras = Array.isArray(item.json.paragraphs) ? item.json.paragraphs : [];
  if (!paras.length) {
    // HTML node failed: fall back to a plain <p> scan of the raw page
    const html = String((pages[i] || {}).json?.data || '');
    paras = [...html.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map(m => m[1].replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"'));
  }
  const kept = [...new Set(paras.map(clean))].filter(p => p.length > 60 && !junk.test(p));
  const text = kept.join('\n\n').slice(0, 7000);
  if (!best || text.length > best.text.length) best = { i, text };
});
const pick = listed[best ? best.i : 0].json;
return [{ json: {
  ok: !!best && best.text.length >= 800,
  source_type: 'article',
  title: pick.title, url: pick.url, outlet: pick.outlet,
  text: best ? best.text : '',
  tried: listed.length,
  reason: 'gnews found ' + listed.length + ' article(s), but their pages were blocked, paywalled or too short'
} }];

// Wikipedia returns the whole page as plain text. Drop the "== Section ==" headings and
// the reference sections, keep the first 7000 characters. Under 800 counts as nothing found.
const lang = $('Apply Settings').first().json.source;
const pages = Object.values(($json.query || {}).pages || {});
const page = pages[0] || {};
const raw = String(page.extract || '');
const cut = raw.search(/\n==+ ?(Notes et références|Références|Voir aussi|Bibliographie|References|See also|Notes)/i);
const text = (cut > 0 ? raw.slice(0, cut) : raw)
  .split('\n').filter(l => l.trim() && !/^==/.test(l.trim())).join('\n\n').slice(0, 7000);
// why there was no news article, for the reply ($() throws if a node did not run)
let reason = 'gnews found no article for this topic';
try { reason = $('List Articles').first().json.reason || reason; } catch (e) {}
try { reason = $('Pick Best Article').first().json.reason; } catch (e) {}
return [{ json: {
  ok: text.length >= 800,
  source_type: 'wikipedia',
  title: String(page.title || ''),
  url: page.pageid ? 'https://' + lang + '.wikipedia.org/?curid=' + page.pageid : '',
  outlet: 'Wikipedia',
  reason, text
} }];

