const parseJson = (t) => { const s = String(t || ''); const a = s.indexOf('{'), b = s.lastIndexOf('}'); try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return {}; } }; // tolerates ```json fences or a sentence around the JSON
// The model wrote this list, so nothing in it is trusted as is (same idea as the lab's Check The Plan):
// parse safely, keep only complete entries, dedupe, cap at 15, cut long fields.
const s = $('Apply Settings').first().json;
const art = $('Article Ready').first().json;
const d = parseJson($json.text);
const cut = (v, n) => String(v || '').replace(/\s+/g, ' ').trim().slice(0, n);
const seen = new Set();
const out = [];
for (const t of (Array.isArray(d.themes) ? d.themes : [])) {
  const theme = cut(t && t.theme, 60) || 'General';
  for (const w of (t && Array.isArray(t.words) ? t.words : [])) {
    const word = cut(w && w.word, 60).toLowerCase();
    if (!word || !w.definition || !w.translation || seen.has(word)) continue;
    seen.add(word);
    out.push({ json: {
      chat_id: s.chat_id, language: s.source, target: s.target,
      word, nature: cut(w.nature, 20), definition: cut(w.definition, 300),
      translation: cut(w.translation, 200), sentence: cut(w.sentence, 400),
      theme, source_type: art.source_type, article_url: art.url, article_title: cut(art.title, 200), fallback_reason: cut(art.reason, 200)
    } });
    if (out.length >= 15) break;
  }
  if (out.length >= 15) break;
}
if (!out.length) throw new Error('The model returned no usable words.');
return out;

// "/add prendre du recul, épanouissement" -> one item per word (max 5 per message).
const s = $json;
const words = [...new Set(s.arg.split(/[,;\n]/)
  .map(w => w.replace(/\s+/g, ' ').trim().toLowerCase())
  .filter(w => w && w.length <= 60))].slice(0, 5);
return words.map(word => ({ json: { chat_id: s.chat_id, language: s.source, target: s.target, word } }));

// One AI answer per asked word, in the same order (Enrich Word keeps failed words in place
// as {error: ...} items), so answer i belongs to word i. Matching by position avoids n8n's
// paired items, which can be missing when several words go through the LLM chain.
const parseJson = (t) => { const s = String(t || ''); const a = s.indexOf('{'), b = s.lastIndexOf('}'); try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return {}; } }; // tolerates ```json fences or a sentence around the JSON
const cut = (v, n) => String(v || '').replace(/\s+/g, ' ').trim().slice(0, n);
const asked = $('Split Added Words').all().map(i => i.json);
const answers = $input.all();
const out = [];
answers.forEach((item, i) => {
  const w = asked[i] || asked[0];
  if (item.json.error) return; // the AI call for this word failed: skip it, keep the others
  const d = parseJson(item.json.text);
  // dropped: words the model calls invalid, or answers missing a definition or translation
  if (d.valid === false || !d.definition || !d.translation) return;
  out.push({ json: {
    chat_id: w.chat_id, language: w.language, target: w.target,
    word: cut(d.word || (asked.length === answers.length ? w.word : ''), 60).toLowerCase(), nature: cut(d.nature, 20),
    definition: cut(d.definition, 300), translation: cut(d.translation, 200),
    sentence: cut(d.sentence, 400), theme: '', source_type: 'manual',
    article_url: '', article_title: ''
  } });
});
const ok = out.filter(x => x.json.word);
if (!ok.length) throw new Error('No valid word to save.'); // error output -> Send AI Failed
return ok;

// The HTTP node returns one reply per word, in the same order: pair them by index.
const words = $('Words To Save').all();
return $input.all().map((reply, i) => {
  const hit = (reply.json.results || [])[0];
  return { json: { ...words[i].json, exists: !!hit, notion_url: hit ? hit.url : '' } };
});

