// Notion returns the new page; put the word fields back next to its URL.
// After its retries, a failed Create Word Page passes on {error: ...} instead of a page.
const w = $('Mark New Or Saved').item.json;
const ok = $json.object === 'page';
const e = $json.error;
const why = $json.message || (typeof e === 'string' ? e : (e && (e.description || e.message))) || 'Notion error';
return { json: { ...w, created: ok, notion_url: ok ? $json.url : '', error: ok ? '' : String(why).slice(0, 200) } };

// HTML for Telegram. Every line is complete on its own, so Split Long Message
// can cut between lines without breaking a tag. Change the look here: one emoji per role.
const ICON = { fresh: '🍓', saved: '🪼', failed: '🌀', article: '⛄️', wiki: '🐚', translation: '🪷', theme: '🐞', link: '🐾' };
const s = $('Apply Settings').first().json;
const items = $input.all().map(i => i.json);
const esc = (v) => String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = (url, label) => url ? ICON.link + ' <a href="' + esc(url) + '">' + label + '</a>' : null; // null lines are dropped at the end
const fresh = items.filter(w => w.created);
const saved = items.filter(w => w.exists);
const failed = items.filter(w => !w.created && !w.exists);
const lines = [];

if (s.route === 'article') {
  const a = items[0] || {};
  if (a.source_type === 'article') lines.push(ICON.article + ' <b>' + esc(a.article_title) + '</b>', link(a.article_url, 'read the article'));
  else lines.push(ICON.wiki + ' <b>' + esc(a.article_title) + '</b> (wikipedia)', link(a.article_url, 'read the page'), '<i>no usable news article: ' + esc(a.fallback_reason) + '.</i>');
  const themes = [...new Set(items.map(w => w.theme))];
  for (const t of themes) {
    lines.push('', ICON.theme + ' <b>' + esc(t) + '</b>');
    for (const w of items.filter(x => x.theme === t)) {
      const mark = w.created ? ICON.fresh : (w.exists ? ICON.saved : ICON.failed);
      lines.push(mark + ' <b>' + esc(w.word) + '</b> ' + esc(w.nature) + ' ' + ICON.translation + ' ' + esc(w.translation));
    }
  }
  const count = [ICON.fresh + ' ' + fresh.length + ' new', ICON.saved + ' ' + saved.length + ' already saved'];
  if (failed.length) count.push(ICON.failed + ' ' + failed.length + ' failed');
  lines.push('', count.join(' · '));
} else {
  for (const w of items) {
    lines.push('');
    if (w.exists) { lines.push(ICON.saved + ' <b>' + esc(w.word) + '</b> is already saved'); lines.push(link(w.notion_url, 'open in notion')); continue; }
    if (!w.created) { lines.push(ICON.failed + ' <b>' + esc(w.word) + '</b> could not be saved: ' + esc(w.error)); continue; }
    lines.push(ICON.fresh + ' <b>' + esc(w.word) + '</b> ' + esc(w.nature));
    lines.push(esc(w.definition));
    lines.push(ICON.translation + ' ' + esc(w.translation));
    if (w.sentence) lines.push('<i>' + esc(w.sentence) + '</i>');
    lines.push(link(w.notion_url, 'open in notion'));
  }
}
return [{ json: { text: lines.filter(l => l !== null).join('\n').trim() } }];

// Telegram allows max 4096 characters per message: cut at line breaks, one item per chunk.
const MAX = 4000;
let rest = String($json.text || '');
const chunks = [];
while (rest.length > MAX) {
  let cut = rest.lastIndexOf('\n', MAX);
  if (cut < MAX / 2) cut = MAX;
  chunks.push(rest.slice(0, cut));
  rest = rest.slice(cut).trimStart();
}
if (rest) chunks.push(rest);
return chunks.map(text => ({ json: { text } }));

// /lang, /level, /time and /words all land here. Each command is checked, and only the
// Notion properties that change are built; Update Settings / Create Settings send them as is.
// Success replies end with 🪷, failures with 🌀.

// Article languages: the 26 GNews supports (Wikipedia is only a fallback for these).
const SOURCES = {
  ar: 'Arabic', bn: 'Bengali', zh: 'Chinese', nl: 'Dutch', en: 'English', fr: 'French',
  de: 'German', el: 'Greek', he: 'Hebrew', hi: 'Hindi', id: 'Indonesian', it: 'Italian',
  ja: 'Japanese', ml: 'Malayalam', mr: 'Marathi', no: 'Norwegian', pt: 'Portuguese',
  pa: 'Punjabi', ro: 'Romanian', ru: 'Russian', es: 'Spanish', sv: 'Swedish', ta: 'Tamil',
  te: 'Telugu', tr: 'Turkish', uk: 'Ukrainian'
};
// Translation languages: any of these, as a code or a full name.
const TARGETS = {
  ...SOURCES,
  af: 'Afrikaans', sq: 'Albanian', am: 'Amharic', hy: 'Armenian', az: 'Azerbaijani', eu: 'Basque',
  be: 'Belarusian', bs: 'Bosnian', bg: 'Bulgarian', my: 'Burmese', ca: 'Catalan', hr: 'Croatian',
  cs: 'Czech', da: 'Danish', et: 'Estonian', fil: 'Filipino', fi: 'Finnish', gl: 'Galician',
  ka: 'Georgian', gu: 'Gujarati', ha: 'Hausa', hu: 'Hungarian', is: 'Icelandic', ig: 'Igbo',
  ga: 'Irish', jv: 'Javanese', kn: 'Kannada', kk: 'Kazakh', km: 'Khmer', ko: 'Korean',
  ku: 'Kurdish', ky: 'Kyrgyz', lo: 'Lao', la: 'Latin', lv: 'Latvian', lt: 'Lithuanian',
  lb: 'Luxembourgish', mk: 'Macedonian', mg: 'Malagasy', ms: 'Malay', mt: 'Maltese', mi: 'Maori',
  mn: 'Mongolian', ne: 'Nepali', ps: 'Pashto', fa: 'Persian', pl: 'Polish', sr: 'Serbian',
  si: 'Sinhala', sk: 'Slovak', sl: 'Slovenian', so: 'Somali', sw: 'Swahili', tl: 'Tagalog',
  tg: 'Tajik', th: 'Thai', ur: 'Urdu', uz: 'Uzbek', vi: 'Vietnamese', cy: 'Welsh',
  xh: 'Xhosa', yi: 'Yiddish', yo: 'Yoruba', zu: 'Zulu'
};
const LEVELS = ['a1', 'a2', 'b1', 'b2', 'c1', 'c2'];

const s = $json;
const arg = s.arg.toLowerCase().trim();
const txt = (v) => ({ rich_text: [{ text: { content: String(v) } }] });
// "fr" or "french" -> "fr"
const find = (word, list) => {
  if (!word) return '';
  if (list[word]) return word;
  return Object.keys(list).find(c => list[c].toLowerCase() === word) || '';
};
const sourceList = Object.keys(SOURCES).map(c => SOURCES[c] + ' (' + c + ')').join(', ');
const pad = (h) => String(h).padStart(2, '0') + ':00';

let ok = false;
let props = {};
let reply = '';

if (s.command === '/lang') {
  const [a, b] = arg.split(/\s+/);
  const src = find(a, SOURCES);
  const tgt = find(b, TARGETS);
  ok = !!(src && tgt && src !== tgt);
  if (ok) {
    props = { 'Source Language': txt(src), 'Target Language': txt(tgt) };
    reply = 'vocab in ' + SOURCES[src] + ', translation in ' + TARGETS[tgt] + ' 🪷\n\navailable languages are ' + sourceList;
  } else {
    reply = 'please use the code of available languages: ' + sourceList
      + '\n\nthe translation language can be any language, as a code or a full name, e.g. /lang fr english 🌀';
  }
} else if (s.command === '/level') {
  const lv = arg.replace(/\s+/g, '');
  ok = LEVELS.includes(lv);
  if (ok) {
    props = { 'Level': txt(lv) };
    reply = 'level set to ' + lv + ' 🪷\nnew vocab and definitions will be tailored to your level';
  } else {
    reply = 'please choose a level from a1 to c2, e.g. /level b2 🌀';
  }
} else if (s.command === '/time') {
  const parts = arg.split(/[\s,]+/).filter(Boolean);
  const hours = [...new Set(parts.map(Number))].sort((x, y) => x - y);
  ok = parts.length >= 1 && parts.length <= 2 && parts.every(p => /^\d{1,2}$/.test(p))
    && hours.every(h => h >= 0 && h <= 23);
  if (ok) {
    props = { 'Recall Hours': txt(hours.join(',')) };
    reply = 'active recall at ' + hours.map(pad).join(' and ') + ' every day 🪷\neach word is sent once a day';
  } else {
    reply = 'please send one or two hours from 0 to 23, e.g. /time 8 or /time 8 20 🌀';
  }
} else if (s.command === '/words') {
  ok = /^\d{1,2}$/.test(arg) && Number(arg) >= 1 && Number(arg) <= 20;
  if (ok) {
    props = { 'Daily Words': txt(Number(arg)) };
    reply = "you'll be tested on " + Number(arg) + ' word' + (Number(arg) > 1 ? 's' : '') + ' every day 🪷';
  } else {
    reply = 'please send a number from 1 to 20, e.g. /words 10 🌀';
  }
}

return [{ json: { ...s, ok, props, reply } }];

// callback_data is "k:<page id>" (I know it!) or "n:<page id>" (No clue!), set by the recall workflow.
// Anyone can send any callback_data to a bot, so it is checked like any other input.
const s = $json;
const m = /^([kn]):([0-9a-f]{32})$/.exec(s.callback_data);
return [{ json: { ...s, valid: !!m, knew: m ? m[1] === 'k' : false, page_id: m ? m[2] : '' } }];

// Spaced repetition: I know it! doubles the interval (1, 2, 4, 8, 16... capped at 180 days),
// No clue! resets it to 1 day. Next review = today + interval.
const b = $('Read Button').first().json;
const tz = $('Config').first().json.timezone;
const props = $json.properties || {};
const owner = ((props['Chat ID'] || {}).rich_text || []).map(t => t.plain_text).join('');
const old = (props['Interval'] || {}).number || 1;
const interval = b.knew ? Math.min(old * 2, 180) : 1;
const next = DateTime.now().setZone(tz).plus({ days: interval }).toISODate();
return [{ json: { ...b, mine: $json.object === 'page' && owner === b.chat_id, interval, next } }];

