={{ (() => {
  const route = $('Normalize The Update').first().json.route;
  const tips = {
    article: 'try a different or broader topic, e.g. /article climat, or try again in a minute',
    add: 'check the spelling, send fewer words at once (max 5), and try again',
    settings: 'check the format with /help and send the command again',
    button: "your answer wasn't recorded, but the word will come back in a later quiz",
    review: 'try /review again in a minute'
  };
  return 'oops 🌀 something went wrong on my side.\n' + (tips[route] || 'try again in a minute, or send /help');
})() }}
